CREATE TRIGGER log_counter AFTER UPDATE OF value ON counters
BEGIN
  INSERT INTO changes VALUES(NEW.id, 'first;entry');
  INSERT INTO changes VALUES(NEW.id, 'value=' || NEW.value);
END

